def physical(k,sgn):
 n=k+7;N=2**n;tt=[]
 for z in range(N):
  gate=z&1;u=1-2*((z>>1)&1);pad=(z>>2)&((1<<k)-1);seed=(z>>(k+2))&7;w=(z>>(k+5))&3
  g=-1 if seed==0 else 1;ev=pad==0 and sgn*g==-1;h=1 if ev else u;s=-1 if w==0 else 1
  tt.append(1 if gate==0 else h*s)
 inf=F(sum(tt[z]!=tt[z^(1<<(k+2))] for z in range(N)),N)
 ck(inf==F(1,16*2**k));return {'k':k,'external_sign':sgn,'q1_query_influence':str(inf),'original_reach_rate4_retirement':str(2*inf)}
